import type { Howl } from "howler";
import { useSettings } from "@/stores/settings";

/** Short 8-bit effects, generated by scripts/gen-sounds.ts into public/sounds. */
export const SOUNDS = {
  tap: "/sounds/tap.wav",
  success: "/sounds/success.wav",
  coin: "/sounds/coin.wav",
  error: "/sounds/error.wav",
  levelUp: "/sounds/level-up.wav",
  warning: "/sounds/warning.wav",
} as const;

export type SoundName = keyof typeof SOUNDS;

const cache = new Map<SoundName, Howl>();

/**
 * Play an effect. Howler is loaded on first use so it never costs anything
 * for players who keep sound off, and never blocks the first render.
 */
export async function playSound(name: SoundName, volume = 0.35): Promise<void> {
  if (typeof window === "undefined" || !useSettings.getState().sound) return;
  try {
    let howl = cache.get(name);
    if (!howl) {
      const { Howl } = await import("howler");
      howl = new Howl({ src: [SOUNDS[name]], volume, preload: true });
      cache.set(name, howl);
    }
    howl.volume(volume);
    howl.play();
  } catch {
    // Audio is decoration; a failure must never break an interaction.
  }
}
